/* ask_main.c -- the whole CLI of scandor. There is deliberately almost nothing here:
 * ask questions against the COMPILED-IN model and witness set. No train, no eval,
 * no bandit, no file loading: every byte this program reads was linked into it.
 * `--about` prints the baked provenance (content hash, model hash, versions) so any
 * binary can be audited back to the exact training that produced it.
 */
#define _POSIX_C_SOURCE 200809L
#include "candor.h"
#include "cd_internal.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "about.h"  /* generated by bake.py at build time */

extern const unsigned char CANDOR_MODEL[];
extern const unsigned CANDOR_MODEL_LEN;
extern const char CANDOR_WITNESS[];
/* CANDOR_ABOUT arrives as a string-literal macro from build/about.h, so it must
 * NOT also be declared extern here (the two spellings expand into each other). */

static int arg_eq(const char *a, const char *b) { return strcmp(a, b) == 0; }

static void usage(const char *prog) {
    fprintf(stderr,
        "usage: %s --context T [--question T] --candidate A [--candidate B ...]\n"
        "           [--head forward|inverse|both] [--json] [--about] [--version]\n"
        "  answers from exact witnessed facts first (REMEMBERED + source, no forward\n"
        "  pass); anything else runs the compiled-in vector forward pass, marked\n"
        "  GUESSED. --about prints baked provenance. No files are read, ever.\n", prog);
}

int main(int argc, char **argv) {
    const char *context = NULL, *question = NULL;
    char *cands[CD_MAX_OPT];
    int n_cand = 0, head_mask = CD_HEAD_FWD, json_out = 0, i;
    struct cd_facts facts;
    const char *entity, *hit = NULL, *src = NULL;
    char err[512] = {0};
    /* argv[0] is the program name; every other token must be a flag. */
    for (i = 1; i < argc; i++) {
        const char *a = argv[i];
        const char *v = (i + 1 < argc) ? argv[i + 1] : NULL;
        if (arg_eq(a, "--about")) { printf("%s\n", CANDOR_ABOUT); return 0; }
        else if (arg_eq(a, "--version")) {
            printf("scandor %s (sealed ask-only; container CDR1 v1-v5)\n",
                   CANDOR_VERSION);
            return 0;
        }
        else if (arg_eq(a, "--help") || arg_eq(a, "-h")) { usage(argv[0]); return 0; }
        else if (arg_eq(a, "--context") && v) { context = v; i++; }
        else if (arg_eq(a, "--question") && v) { question = v; i++; }
        else if (arg_eq(a, "--candidate") && v) {
            if (n_cand < CD_MAX_OPT) cands[n_cand++] = (char *)v;
            i++;
        }
        else if (arg_eq(a, "--head") && v) {
            if (arg_eq(v, "both")) head_mask = 3;
            else if (arg_eq(v, "inverse")) head_mask = CD_HEAD_INV;
            else head_mask = CD_HEAD_FWD;
            i++;
        }
        else if (arg_eq(a, "--json")) json_out = 1;
        else { fprintf(stderr, "unknown argument: %s\n", a); usage(argv[0]); return 2; }
    }
    if (!context || n_cand == 0) { usage(argv[0]); return 2; }

    facts.v = NULL;
    facts.n = 0;
    if (cd_fact_load_mem(CANDOR_WITNESS, &facts, err, sizeof err) != 0) {
        fprintf(stderr, "embedded witness unreadable (build defect): %s\n", err);
        return 1;
    }
    entity = cd_fact_resolve_entity(&facts, context);
    if (entity && cd_fact_lookup(&facts, entity, cands, n_cand, &hit, &src)) {
        if (json_out) {
            printf("{\"verdict\": \"remembered\", \"answer\": \"");
            for (const char *q = hit; *q; q++) {
                if (*q == '"' || *q == '\\') putchar('\\');
                putchar(*q);
            }
            printf("\", \"source\": \"");
            if (src) for (const char *q = src; *q; q++) {
                if (*q == '"' || *q == '\\') putchar('\\');
                putchar(*q);
            }
            printf("\"}\n");
        } else {
            printf("\n  REMEMBERED: %s is %s.\n", entity, hit);
            printf("    source: %s\n", src && *src ? src : "(witnessed)");
            printf("    (%zu witnessed facts compiled in; forward pass not run)\n",
                   cd_fact_count(&facts));
        }
        cd_fact_free(&facts);
        return 0;
    }
    {
        /* No exact fact: the compiled-in forward pass, marked as a guess. The
         * model bytes below were linked at build time; cd_load_mem parses the
         * same container a file load would, through the same code. */
        struct cd_model *m = cd_load_mem(CANDOR_MODEL, CANDOR_MODEL_LEN, err, sizeof err);
        int rc;
        if (!entity)
            printf("\n  no known entity in context -- vector guess follows (GUESSED):\n");
        else
            printf("\n  nothing exactly witnessed for '%s' among %d candidate(s) -- "
                   "vector guess follows (GUESSED):\n", entity, n_cand);
        if (!m) {
            fprintf(stderr, "embedded model unreadable (build defect): %s\n", err);
            cd_fact_free(&facts);
            return 1;
        }
        if (json_out)
            rc = cd_ask_mem(m, context, question, cands, n_cand, head_mask);
        else
            rc = cd_ask_show(m, context, question, cands, n_cand, head_mask);
        cd_model_free(m);
        cd_fact_free(&facts);
        return rc;
    }
}
